import './style.css'
import Vue from 'vue'
import VueRouter from 'vue-router'
import App from './App.vue'
import FrontPage from './App.vue'  // your main page component file

// Tell Vue to use VueRouter
Vue.use(VueRouter)

// Define your routes
const routes = [
  { path: '/', component: FrontPage },
  // add more routes if needed
]

// Create router instance
const router = new VueRouter({
  mode: 'hash',            // or 'history', depending on your server config
  base: '/vue-pages/',     // your base URL (GitHub pages or similar)
  routes,
})

// Create Vue instance and pass router
new Vue({
  router,
  render: h => h(App)
}).$mount('#app')
